import{_ as n,C as d,o as i,c,j as o,a,E as s,a3 as r}from"./chunks/framework.BJ2rlPXv.js";const _=JSON.parse('{"title":"Runner, Flows and History","description":"","frontmatter":{},"headers":[],"relativePath":"tui/runner.md","filePath":"tui/runner.md","lastUpdated":1795474269000}'),l={name:"tui/runner.md"};function h(p,e,u,f,m,y){const t=d("Screen");return i(),c("div",null,[e[0]||(e[0]=o("h1",{id:"runner-flows-and-history",tabindex:"-1"},[a("Runner, Flows and History "),o("a",{class:"header-anchor",href:"#runner-flows-and-history","aria-label":'Permalink to "Runner, Flows and History"'},"​")],-1)),e[1]||(e[1]=o("h2",{id:"command-palette",tabindex:"-1"},[a("Command palette "),o("a",{class:"header-anchor",href:"#command-palette","aria-label":'Permalink to "Command palette"'},"​")],-1)),s(t,{name:"palette",caption:"ctrl+k: fuzzy search over operations, runs, flows and environments"}),e[2]||(e[2]=r('<p><code>ctrl+k</code> opens a fuzzy search over everything you can do: every operation (open it in the editor), test runs, flows, environments, the history and &quot;copy as cURL&quot;. Type a few letters of each word, in any order (<code>get users</code>, <code>flow life</code>, <code>env prod</code>), then <code>enter</code>.</p><h2 id="runner" tabindex="-1">Runner <a class="header-anchor" href="#runner" aria-label="Permalink to &quot;Runner&quot;">​</a></h2>',2)),s(t,{name:"runner",caption:"Run All operations from the palette: results stream in with a progress bar"}),e[3]||(e[3]=r('<p>The runner runs operations and flows with the same engine as <code>lazyapi run</code> and shows results as they finish.</p><ul><li><code>R</code> in the request list runs the spec&#39;s read-only operations (<code>GET</code>, <code>HEAD</code>, <code>OPTIONS</code>).</li><li>The palette also offers <strong>All operations</strong> (writes included), each <strong>Tag</strong>, <strong>All flows</strong> and each <code>.lazyapi/flows/*.js</code>. Runs that may change data (every method, or flows) ask <code>y</code>/<code>N</code> first and show the environment they will use.</li></ul><p>The header shows a progress bar and the passed / failed / skipped counts. When the run ends, the cursor jumps to the first failure. The right side is the <a href="./response-preview">response view</a> of the selected result (status, body, checks, console, timeline), and for a flow it lists every request the flow sent. <code>enter</code> on a flow expands it into its steps (<code>▸</code>/<code>▾</code>): selecting a step shows that request, its response and its automatic checks (request, status, contract). <code>F</code> keeps only failures, <code>e</code> opens the operation in the editor, <code>R</code> runs again, <code>esc</code> stops a run in progress.</p><p>The run uses the active environment: its server, env file, vars, credentials and <code>http:</code> options.</p><p><strong>Data files.</strong> The palette also lists the CSV files and JSON arrays next to the spec and in <code>data/</code> (<code>Data · .lazyapi/data/users.csv → read-only operations</code>, <code>→ all operations</code>, <code>→ flows</code>). The run goes once per row, like <a href="/v2/cli/run#data-driven-runs"><code>run --data</code></a>: results are labeled <code>[#n]</code>, and the confirmation shows the number of rows.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2>',6)),s(t,{name:"history",caption:"H: every response is recorded, without credentials"}),e[4]||(e[4]=r('<p>Every request sent from the TUI (list or editor) is recorded per spec. <code>H</code> in the list (or the palette) opens it, newest first.</p><ul><li><code>enter</code> replays the request: it opens in the editor with the method, path, params, query, headers and body it was sent with, on top of the operation as the spec defines it.</li><li><code>d</code> compares the response with the previous response of the same operation.</li><li><code>x</code> compares it with the example saved in the spec for that status (<code>ctrl+e</code> in the editor saves one).</li></ul><p>JSON bodies are compared with sorted keys, so only real changes show up.</p><h3 id="what-is-stored" tabindex="-1">What is stored <a class="header-anchor" href="#what-is-stored" aria-label="Permalink to &quot;What is stored&quot;">​</a></h3><p>History lives in <code>.lazyapi/.local/history.jsonl</code> next to the spec (git-ignored; <code>LAZYAPI_HISTORY_DIR</code> moves it elsewhere), with the newest 200 requests and <code>0600</code> permissions. Credentials are not stored:</p><ul><li>environment values and auth secrets are never written;</li><li>headers and query parameters that look like credentials (<code>Authorization</code>, <code>Cookie</code>, <code>*token*</code>, <code>*key*</code>, <code>*secret*</code>, <code>*password*</code>) are redacted unless they are a plain <code>{{env.X}}</code> reference;</li><li>bodies are stored as written in the editor, so <code>{{env.PASSWORD}}</code> stays a template;</li><li>console output and response cookies are dropped, and bodies over 256 KB are cut.</li></ul><p>Replaying a redacted header uses the operation&#39;s current value. <code>X</code> in the history deletes it (after <code>y</code>). Set <code>LAZYAPI_NO_HISTORY=1</code> to disable the history, or <code>LAZYAPI_HISTORY_DIR</code> to keep it somewhere else.</p>',7))])}const v=n(l,[["render",h]]);export{_ as __pageData,v as default};
